  /**
   * Class representing a stroke.
   *
   * @see https://api.onlyoffice.com/docs/office-api/usage-api/pdf-api/ApiStroke/
   */
  export interface ApiStroke {
    /**
     * Returns the beginning arrow properties of the stroke.
     *
     * @since 9.5.0
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/pdf-api/ApiStroke/Methods/GetBeginArrow/
     */
    GetBeginArrow(): object | null;

    /**
     * Returns a type of the ApiStroke class.
     *
     * @example
     * ```js
     * // What class identifier does a border line report in a PDF?
     *
     * // Print the type classification of a border line in a PDF
     *
     * const doc = Api.GetDocument();
     * const page = doc.GetPage(0);
     *
     * const gs1 = Api.CreateGradientStop(Api.RGB(255, 213, 191), 0);
     * const gs2 = Api.CreateGradientStop(Api.RGB(255, 111, 61), 100000);
     * const fill = Api.CreateLinearGradientFill([gs1, gs2], 5400000);
     * const fill1 = Api.CreateSolidFill(Api.RGB(51, 51, 51));
     * const stroke = Api.CreateStroke(3 * 36000, fill1);
     * const shape = Api.CreateShape("flowChartMagneticTape", 300 * 36000, 130 * 36000, fill, stroke);
     *
     * const classType = stroke.GetClassType();
     * const docContent = shape.GetContent();
     * const paragraph = docContent.GetElement(0);
     * paragraph.SetJc("left");
     * paragraph.AddText("Class Type = " + classType);
     * page.AddObject(shape);
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/pdf-api/ApiStroke/Methods/GetClassType/
     */
    GetClassType(): "stroke";

    /**
     * Gets the dash type of the stroke.
     *
     * @returns returns dash type ("solid", "dash", etc.) or null.
     *
     * @example
     * ```js
     * // What dash pattern is applied to a border line in a PDF?
     *
     * // Extract and show the line style for a border in a PDF
     *
     * const doc = Api.GetDocument();
     * const page = doc.GetPage(0);
     *
     * let fill = Api.CreateSolidFill(Api.CreateRGBColor(255, 200, 100));
     * let stroke = Api.CreateStroke(36000, Api.CreateSolidFill(Api.CreateRGBColor(0, 0, 255)));
     * let shape = Api.CreateShape("rect", 100 * 36000, 50 * 36000, fill, stroke);
     * shape.SetPosition(2000000, 1000000);
     * page.AddObject(shape);
     * let content = shape.GetContent();
     * let paragraph = content.GetElement(0);
     * let retrievedStroke = shape.GetLine();
     * let dashType = retrievedStroke.GetDashType();
     * paragraph.AddText("Dash type: " + (dashType ? dashType : "not set"));
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/pdf-api/ApiStroke/Methods/GetDashType/
     */
    GetDashType(): DashType | null;

    /**
     * Returns the ending arrow properties of the stroke.
     *
     * @since 9.5.0
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/pdf-api/ApiStroke/Methods/GetEndArrow/
     */
    GetEndArrow(): object | null;

    /**
     * Gets the fill (color) of the stroke.
     *
     * @example
     * ```js
     * // What color is the border line filled with in a PDF?
     *
     * // Check and display the fill properties of a border in a PDF
     *
     * const doc = Api.GetDocument();
     * const page = doc.GetPage(0);
     *
     * let fill = Api.CreateSolidFill(Api.CreateRGBColor(255, 200, 100));
     * let stroke = Api.CreateStroke(2 * 36000, Api.CreateSolidFill(Api.CreateRGBColor(0, 0, 255)));
     * let shape = Api.CreateShape("rect", 100 * 36000, 50 * 36000, fill, stroke);
     * shape.SetPosition(2000000, 1000000);
     * page.AddObject(shape);
     * let content = shape.GetContent();
     * let paragraph = content.GetElement(0);
     * let strokeObj = shape.GetLine();
     * if (strokeObj) {
     *     let strokeFill = strokeObj.GetFill();
     *     if (strokeFill) {
     *         paragraph.AddText("Stroke fill type: " + strokeFill.GetType());
     *     }
     * }
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/pdf-api/ApiStroke/Methods/GetFill/
     */
    GetFill(): ApiFill | null;

    /**
     * Gets the width of the stroke in English Metric Units.
     *
     * @example
     * ```js
     * // What is the border thickness measured in units in a PDF?
     *
     * // Read and display the line width of a border in a PDF
     *
     * const doc = Api.GetDocument();
     * const page = doc.GetPage(0);
     *
     * let fill = Api.CreateSolidFill(Api.CreateRGBColor(255, 200, 100));
     *
     * // Shape with 1pt border
     * let stroke1 = Api.CreateStroke(1 * 12700, Api.CreateSolidFill(Api.CreateRGBColor(0, 0, 255)));
     * let shape1 = Api.CreateShape("rect", 50 * 36000, 30 * 36000, fill, stroke1);
     * shape1.SetPosition(2000000, 1000000);
     * page.AddObject(shape1);
     * let content1 = shape1.GetContent();
     * let para1 = content1.GetElement(0);
     * let width1 = shape1.GetLine().GetWidth();
     * para1.AddText("1pt: " + width1 + " EMU");
     *
     * // Shape with 2.5pt border
     * let stroke2 = Api.CreateStroke(2.5 * 12700, Api.CreateSolidFill(Api.CreateRGBColor(255, 0, 0)));
     * let shape2 = Api.CreateShape("rect", 50 * 36000, 30 * 36000, fill, stroke2);
     * shape2.SetPosition(2000000, 2000000);
     * page.AddObject(shape2);
     * let content2 = shape2.GetContent();
     * let para2 = content2.GetElement(0);
     * let width2 = shape2.GetLine().GetWidth();
     * para2.AddText("2.5pt: " + width2 + " EMU");
     *
     * // Shape with 5pt border
     * let stroke3 = Api.CreateStroke(5 * 12700, Api.CreateSolidFill(Api.CreateRGBColor(0, 255, 0)));
     * let shape3 = Api.CreateShape("rect", 50 * 36000, 30 * 36000, fill, stroke3);
     * shape3.SetPosition(2000000, 3000000);
     * page.AddObject(shape3);
     * let content3 = shape3.GetContent();
     * let para3 = content3.GetElement(0);
     * let width3 = shape3.GetLine().GetWidth();
     * para3.AddText("5pt: " + width3 + " EMU");
     * ```
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/pdf-api/ApiStroke/Methods/GetWidth/
     */
    GetWidth(): EMU | null;

    /**
     * Sets the beginning arrow of the stroke.
     *
     * @param type - The type of the beginning arrow.
     * @param width - The width of the beginning arrow.
     * @param length - The length of the beginning arrow.
     * @default width = "medium"
     * @default length = "medium"
     * @since 9.5.0
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/pdf-api/ApiStroke/Methods/SetBeginArrow/
     */
    SetBeginArrow(type: LineEndType, width?: LineEndSize, length?: LineEndSize): boolean;

    /**
     * Sets the ending arrow of the stroke.
     *
     * @param type - The type of the ending arrow.
     * @param width - The width of the ending arrow.
     * @param length - The length of the ending arrow.
     * @default width = "medium"
     * @default length = "medium"
     * @since 9.5.0
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/pdf-api/ApiStroke/Methods/SetEndArrow/
     */
    SetEndArrow(type: LineEndType, width?: LineEndSize, length?: LineEndSize): boolean;
  }

